def line_total(price, quantity, discount_percent=0):
    # Validate price: must be finite and non-negative
    if not isinstance(price, (int, float, str)) or isinstance(price, bool):
        raise ValueError("price must be a number")
    try:
        price_decimal = Decimal(str(price))
    except:
        raise ValueError("price must be a valid number")
    if price_decimal < 0 or not price_decimal.is_finite():
        raise ValueError("price must be non-negative and finite")

    # Validate quantity: must be integer (not float, not bool) and non-negative
    if isinstance(quantity, bool) or isinstance(quantity, float):
        raise ValueError("quantity must be an integer")
    if not isinstance(quantity, int):
        raise ValueError("quantity must be an integer")
    if quantity < 0:
        raise ValueError("quantity must be non-negative")
    try:
        quantity_decimal = Decimal(str(quantity))
    except:
        raise ValueError("quantity must be a valid number")

    # Validate discount: must be finite and between 0 and 100 inclusive
    if isinstance(discount_percent, bool):
        raise ValueError("discount_percent must be a number")
    try:
        discount_decimal = Decimal(str(discount_percent))
    except:
        raise ValueError("discount_percent must be a valid number")
    if not discount_decimal.is_finite():
        raise ValueError("discount_percent must be finite")
    if discount_decimal < 0 or discount_decimal > 100:
        raise ValueError("discount_percent must be between 0 and 100")

    # Calculate with Decimal, apply discount before rounding
    total = price_decimal * quantity_decimal * (1 - discount_decimal / 100)
    return total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
