        raise ValueError("discount_percent must be between 0 and 100")

    # Validate shipping: must be finite and non-negative
    if isinstance(shipping, bool):
        raise ValueError("shipping must be a number")
    try:
        shipping_decimal = Decimal(str(shipping))
    except:
        raise ValueError("shipping must be a valid number")
    if not shipping_decimal.is_finite() or shipping_decimal < 0:
        raise ValueError("shipping must be non-negative and finite")

